const body = $json.body ?? {};

if (!body.extraction_id) {
  return [{ json: { valid: false, statusCode: 400, error: 'Missing "extraction_id".' } }];
}
if (!Array.isArray(body.key_terms)) {
  return [{ json: { valid: false, statusCode: 400, error: 'Missing or invalid "key_terms" array.' } }];
}

return [{ json: { valid: true, extraction_id: body.extraction_id, key_terms: body.key_terms } }];

const updated = Array.isArray($json) ? $json[0] : $json;
if (!updated || !updated.id) {
  return [{ json: { valid: false, statusCode: 404, error: 'No extraction found for that id — nothing was updated.' } }];
}
return [{ json: { success: true, id: updated.id, key_terms: updated.key_terms } }];

return [{
  json: {
    valid: false,
    statusCode: 502,
    error: 'Saving the correction failed after 3 attempts — the database update did not go through. The value shown in the app has NOT been persisted.'
  }
}];
